# remove duplicate keys via dict semantics; longest first
items=sorted(D.items(), key=lambda kv:len(kv[0]), reverse=True)
def trans(z):
    # Replace phrases/words while preserving punctuation.
    out=z
    for zh,vi in items:
        out=out.replace(zh,vi)
    # common grammatical leftovers
    reps=[('，所以',' nên '),('，但是',' nhưng '),('，并且',' và đồng thời '),('，也',' cũng '),('，还',' vẫn '),('。','.'),('，',', '),('、',', '),('？','?'),('！','!')]
    for a,c in reps: out=out.replace(a,c)
    # remove awkward doubled spaces
    out=re.sub(r'\s+',' ',out).strip()
    return out

# Only replace meanings that are blank or still contain Chinese characters.
for q in b:
    if not q.get('meaning','').strip() or re.search(r'[\u3400-\u9fff]', q.get('meaning','')):
        q['meaning']=trans(q['audio'])
# Special exact correction
q=next((x for x in b if x['audio']=='我有点累。'),None)
if q:q['meaning']='Tôi hơi mệt.'
# Validate no Chinese remains.
bad=[q for q in b if re.search(r'[\u3400-\u9fff]',q.get('meaning','')) or not q.get('meaning','').strip()]
print('remaining bad meanings:',len(bad))
for q in bad[:20]: print(q['audio'],'=>',q['meaning'])
newjson=json.dumps(b,ensure_ascii=False,indent=1)
s=s[:m.start(1)]+newjson+s[m.end(1):]
open(p,'w',encoding='utf8').write(s)
